fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Use zip to pair elements, then map to comparison result
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x < y)
        .collect()
}